[{"order":1,"type":"heading","text":"Unit Testing in Spring Boot with JUnit and Mockito"},{"order":2,"type":"paragraph","text":"Unit testing is a crucial part of software development, ensuring that individual components of your application function as expected. In the context of Spring Boot, unit testing allows you to isolate and test your beans, services, and controllers without relying on the entire application context. This tutorial will guide you through writing effective unit tests using JUnit and Mockito."},{"order":3,"type":"subheading","text":"Prerequisites"},{"order":4,"type":"bullet_point","text":"Basic understanding of Spring Boot and Dependency Injection."},{"order":5,"type":"bullet_point","text":"Familiarity with Java and Maven or Gradle."},{"order":6,"type":"bullet_point","text":"An IDE such as IntelliJ IDEA or Eclipse."},{"order":7,"type":"subheading","text":"Setting up a Spring Boot Project"},{"order":8,"type":"paragraph","text":"If you don't already have a Spring Boot project, you can create one using Spring Initializr (start.spring.io). Add the 'Spring Web' dependency to create a simple REST API. Also, include the 'Spring Boot Starter Test' dependency, which includes JUnit and Mockito."},{"order":9,"type":"subheading","text":"Dependencies"},{"order":10,"type":"paragraph","text":"The 'Spring Boot Starter Test' dependency includes the necessary libraries for unit testing. Here's how it looks in your `pom.xml` (Maven):"},{"order":11,"type":"code","text":"<dependency>
	<groupId>org.springframework.boot</groupId>
	<artifactId>spring-boot-starter-test</artifactId>
	<scope>test</scope>
</dependency>"},{"order":12,"type":"paragraph","text":"Or, in your `build.gradle` (Gradle):"},{"order":13,"type":"code","text":"testImplementation 'org.springframework.boot:spring-boot-starter-test'"},{"order":14,"type":"subheading","text":"Creating a Simple Service"},{"order":15,"type":"paragraph","text":"Let's create a simple service that we can then unit test. This service will retrieve a greeting message."},{"order":16,"type":"code","text":"package com.example.demo.service;

import org.springframework.stereotype.Service;

@Service
public class GreetingService {

    public String getGreeting(String name) {
        return "Hello, " + name + "!";
    }
}"},{"order":17,"type":"subheading","text":"Writing a Unit Test for the Service"},{"order":18,"type":"paragraph","text":"Now, let's write a unit test for the `GreetingService`. We'll use JUnit for structuring the test and Mockito for mocking any dependencies (although in this simple example, there are no dependencies to mock)."},{"order":19,"type":"code","text":"package com.example.demo.service;

import org.junit.jupiter.api.Test;
import org.springframework.beans.factory.annotation.Autowired;
import org.springframework.boot.test.context.SpringBootTest;

import static org.junit.jupiter.api.Assertions.assertEquals;

@SpringBootTest
public class GreetingServiceTest {

    @Autowired
    private GreetingService greetingService;

    @Test
    public void testGetGreeting() {
        String name = "World";
        String expectedGreeting = "Hello, World!";
        String actualGreeting = greetingService.getGreeting(name);
        assertEquals(expectedGreeting, actualGreeting);
    }
}"},{"order":20,"type":"paragraph","text":"Explanation:"},{"order":21,"type":"bullet_point","text":"`@SpringBootTest`: This annotation tells Spring Boot to load the application context. While this is technically an integration test, it can be used for unit tests as well, especially when you need Spring's dependency injection."},{"order":22,"type":"bullet_point","text":"`@Autowired`: This injects an instance of `GreetingService` into the test class."},{"order":23,"type":"bullet_point","text":"`@Test`: This annotation marks the `testGetGreeting` method as a test case."},{"order":24,"type":"bullet_point","text":"`assertEquals`: This assertion checks if the `actualGreeting` matches the `expectedGreeting`."},{"order":25,"type":"subheading","text":"Using Mockito for Mocking Dependencies"},{"order":26,"type":"paragraph","text":"Mockito is a mocking framework that allows you to create mock objects for your dependencies. This is useful when you want to isolate the unit under test and avoid relying on external resources or complex dependencies. Let's modify our example to include a dependency that we can mock."},{"order":27,"type":"subheading","text":"Creating a Service with a Dependency"},{"order":28,"type":"code","text":"package com.example.demo.service;

import org.springframework.stereotype.Service;

@Service
public class MessageSource {

    public String getMessage() {
        // Simulate fetching a message from a database or external source
        return "Hello from MessageSource!";
    }
}"},{"order":29,"type":"code","text":"package com.example.demo.service;

import org.springframework.beans.factory.annotation.Autowired;
import org.springframework.stereotype.Service;

@Service
public class GreetingService {

    private final MessageSource messageSource;

    @Autowired
    public GreetingService(MessageSource messageSource) {
        this.messageSource = messageSource;
    }

    public String getGreeting(String name) {
        return messageSource.getMessage() + " " + name + "!";
    }
}"},{"order":30,"type":"subheading","text":"Writing a Unit Test with Mockito"},{"order":31,"type":"code","text":"package com.example.demo.service;

import org.junit.jupiter.api.Test;
import org.junit.jupiter.api.extension.ExtendWith;
import org.mockito.InjectMocks;
import org.mockito.Mock;
import org.mockito.junit.jupiter.MockitoExtension;

import static org.junit.jupiter.api.Assertions.assertEquals;
import static org.mockito.Mockito.when;

@ExtendWith(MockitoExtension.class)
public class GreetingServiceTest {

    @Mock
    private MessageSource messageSource;

    @InjectMocks
    private GreetingService greetingService;

    @Test
    public void testGetGreeting() {
        // Define the behavior of the mock
        when(messageSource.getMessage()).thenReturn("Mocked Message");

        String name = "World";
        String expectedGreeting = "Mocked Message World!";
        String actualGreeting = greetingService.getGreeting(name);
        assertEquals(expectedGreeting, actualGreeting);
    }
}"},{"order":32,"type":"paragraph","text":"Explanation:"},{"order":33,"type":"bullet_point","text":"`@ExtendWith(MockitoExtension.class)`: This annotation initializes Mockito annotations."},{"order":34,"type":"bullet_point","text":"`@Mock`: This annotation creates a mock instance of `MessageSource`."},{"order":35,"type":"bullet_point","text":"`@InjectMocks`: This annotation creates an instance of `GreetingService` and injects the mocked `MessageSource` into it."},{"order":36,"type":"bullet_point","text":"`when(messageSource.getMessage()).thenReturn("Mocked Message")`: This defines the behavior of the mock. When `messageSource.getMessage()` is called, it will return "Mocked Message"."},{"order":37,"type":"subheading","text":"Testing Controllers"},{"order":38,"type":"paragraph","text":"Unit testing controllers involves mocking the service layer and verifying that the controller correctly handles requests and responses. Let's create a simple controller."},{"order":39,"type":"code","text":"package com.example.demo.controller;

import com.example.demo.service.GreetingService;
import org.springframework.beans.factory.annotation.Autowired;
import org.springframework.web.bind.annotation.GetMapping;
import org.springframework.web.bind.annotation.RequestParam;
import org.springframework.web.bind.annotation.RestController;

@RestController
public class GreetingController {

    private final GreetingService greetingService;

    @Autowired
    public GreetingController(GreetingService greetingService) {
        this.greetingService = greetingService;
    }

    @GetMapping("/greeting")
    public String getGreeting(@RequestParam(name = "name", defaultValue = "World") String name) {
        return greetingService.getGreeting(name);
    }
}"},{"order":40,"type":"subheading","text":"Writing a Unit Test for the Controller"},{"order":41,"type":"code","text":"package com.example.demo.controller;

import com.example.demo.service.GreetingService;
import org.junit.jupiter.api.Test;
import org.junit.jupiter.api.extension.ExtendWith;
import org.mockito.InjectMocks;
import org.mockito.Mock;
import org.mockito.junit.jupiter.MockitoExtension;

import static org.junit.jupiter.api.Assertions.assertEquals;
import static org.mockito.Mockito.when;

@ExtendWith(MockitoExtension.class)
public class GreetingControllerTest {

    @Mock
    private GreetingService greetingService;

    @InjectMocks
    private GreetingController greetingController;

    @Test
    public void testGetGreeting() {
        String name = "TestName";
        String expectedGreeting = "Hello, TestName!";

        when(greetingService.getGreeting(name)).thenReturn(expectedGreeting);

        String actualGreeting = greetingController.getGreeting(name);

        assertEquals(expectedGreeting, actualGreeting);
    }

    @Test
    public void testGetGreetingWithDefaultName() {
        String expectedGreeting = "Hello, World!";

        when(greetingService.getGreeting("World")).thenReturn(expectedGreeting);

        String actualGreeting = greetingController.getGreeting("World");

        assertEquals(expectedGreeting, actualGreeting);
    }
}"},{"order":42,"type":"paragraph","text":"Explanation:"},{"order":43,"type":"bullet_point","text":"We mock the `GreetingService` and inject it into the `GreetingController`."},{"order":44,"type":"bullet_point","text":"We define the behavior of the mocked service using `when(...).thenReturn(...)`."},{"order":45,"type":"bullet_point","text":"We call the controller method and assert that the returned value matches the expected value."},{"order":46,"type":"subheading","text":"Best Practices"},{"order":47,"type":"bullet_point","text":"Write focused unit tests that test a single unit of functionality."},{"order":48,"type":"bullet_point","text":"Use Mockito to isolate your units from external dependencies."},{"order":49,"type":"bullet_point","text":"Follow the Arrange-Act-Assert pattern in your tests."},{"order":50,"type":"bullet_point","text":"Name your tests descriptively to indicate what they are testing."},{"order":51,"type":"subheading","text":"Conclusion"},{"order":52,"type":"paragraph","text":"Unit testing is an essential practice in Spring Boot development. By using JUnit and Mockito, you can effectively test your application's components in isolation, ensuring code quality and maintainability. This tutorial provided a basic overview of writing unit tests; explore more advanced Mockito features and testing techniques as your application grows in complexity."}]
